import{_ as u,a0 as a,w as r,s as e,ao as o,I as i,x as n,a1 as s,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"在虛擬機中運行 Linux 的十大優點 | LCTT x X-CMD","titleTemplate":false,"description":"在虛擬機中運行 Linux 的十大優點 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在虛擬機中運行 Linux 的十大優點 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在虛擬機中運行 Linux 的十大優點 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220427 10 Reasons to Run Linux in Virtual Machines","title":"在虛擬機中運行 Linux 的十大優點","tag":"202205","desc":""},"relativePath":"202205/20220427 10 Reasons to Run Linux in Virtual Machines.md","filePath":"[post].md"}'),d={name:"202205/20220427 10 Reasons to Run Linux in Virtual Machines.md"};function x(f,t,m,L,b,T){const l=a("Link");return r(),e("div",null,[t[37]||(t[37]=o('<h1 id="在虛擬機中運行-linux-的十大優點" tabindex="-1">在虛擬機中運行 Linux 的十大優點 <a class="header-anchor" href="#在虛擬機中運行-linux-的十大優點" aria-label="Permalink to “在虛擬機中運行 Linux 的十大優點”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/04/093523wlzslifl2cp9papp.jpg" alt=""></p><blockquote><p>你可以在虛擬機環境裏運行任何操作系統，不論是測試還是為了某種需要。</p></blockquote><p>對於 Linux 而言，它在虛擬環境下的性能會優於其他操作系統。即便你可能會猶豫是否在物理機（裸金屬）上安裝 Linux 系統，你仍然可以在虛擬機中安裝一個性能幾乎和物理機一樣好的 Linux 系統。</p><p>當然，這並不意味着宿主系統為 Linux 時你就不能在虛擬機實例中安裝 Linux 了。</p><p>更何況，你在虛擬環境下使用 Linux 系統有許多好處。大致如下。</p><h3 id="在虛擬環境下運行-linux-之前的注意事項" tabindex="-1">在虛擬環境下運行 Linux 之前的注意事項 <a class="header-anchor" href="#在虛擬環境下運行-linux-之前的注意事項" aria-label="Permalink to “在虛擬環境下運行 Linux 之前的注意事項”">​</a></h3><p>在虛擬環境下運行 Linux 或許並不是艱鉅的任務，但仍有以下幾點你需謹記。</p><ul><li>虛擬機的性能取決於宿主機的性能，如果你並沒有足夠的系統資源分配給虛擬機，那麼虛擬機的使用體驗註定不會很好。</li><li>某些特性僅在物理機（裸金屬）上生效，包括硬件加速以及圖形（顯卡）驅動等。</li><li>密集的磁盤 I/O 任務性能會十分受限，例如遊戲測試場景。</li><li>用户的 Linux 虛擬機實例體驗會根據你所使用的虛擬化程序而發生變化，這些虛擬化程序包括 VMware、VirtualBox、GNOME Boxes 以及 Hyper-V 。</li></ul><p>此外，你應當列出你的需求，並根據這些需求選定適當的虛擬化程序來運行你的 Linux 實例。</p><h3 id="十條在虛擬環境中運行-linux-的優點" tabindex="-1">十條在虛擬環境中運行 Linux 的優點 <a class="header-anchor" href="#十條在虛擬環境中運行-linux-的優點" aria-label="Permalink to “十條在虛擬環境中運行 Linux 的優點”">​</a></h3>',11)),i("p",null,[t[1]||(t[1]=n("儘管運行虛擬化 Linux 實例極具吸引力，你仍然應當首先考慮當前使用的宿主系統中已有的選擇。例如，如果你不需要圖形化桌面，或許利用 Windows 操作系統中的 ",-1)),s(l,{href:"https://itsfoss.com/install-bash-on-windows/"},{default:p(()=>[...t[0]||(t[0]=[n("WSL 安裝 Linux",-1)])]),_:1}),t[2]||(t[2]=n(" 就可以滿足你的需求。",-1))]),t[38]||(t[38]=i("p",null,"一旦你確定了使用虛擬機，那麼這些優點將會如影隨形：",-1)),t[39]||(t[39]=i("h4",{id:"_1、部署簡便",tabindex:"-1"},[n("1、部署簡便 "),i("a",{class:"header-anchor",href:"#_1、部署簡便","aria-label":"Permalink to “1、部署簡便”"},"​")],-1)),t[40]||(t[40]=i("p",null,[i("img",{src:"https://itsfoss.com/wp-content/uploads/2022/04/easy-setup-linux-vm.jpg",alt:"部署簡便"})],-1)),t[41]||(t[41]=i("p",null,"與在傳統物理機（裸金屬）上安裝 Linux 相比，在虛擬機中部署一般會容易許多。",-1)),t[42]||(t[42]=i("p",null,[n("對於基於 Ubuntu 的發行版而言，像 VMware 這樣的虛擬化程序會提供一個 "),i("strong",null,"快速安裝"),n(" 的選項，你僅需輸入用户名和密碼，其餘過程將自動完成而無需其他操作。你無需手動設置分區、引導程序以及更多高級設置。")],-1)),t[43]||(t[43]=i("p",null,"某些情況下，一些發行版的開發者會同時提供針對特定虛擬機的預構建鏡像，只需打開就可使用。這就好像一個便攜式虛擬機鏡像，隨時可以開箱即用。",-1)),i("p",null,[t[4]||(t[4]=n("例如，在 ",-1)),s(l,{href:"https://itsfoss.com/install-arch-linux-virtualbox/"},{default:p(()=>[...t[3]||(t[3]=[n("這裏",-1)])]),_:1}),t[5]||(t[5]=n(" 你將看到如何在虛擬機中安裝 Arch Linux 發行版。",-1))]),t[44]||(t[44]=o('<p>對於其他的發行版，你或許仍需要進行一些配置，但一般都會有快速安裝的選項令你可以輕鬆部署。</p><h4 id="_2、不會影響宿主機" tabindex="-1">2、不會影響宿主機 <a class="header-anchor" href="#_2、不會影響宿主機" aria-label="Permalink to “2、不會影響宿主機”">​</a></h4><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/isolated-linux-vm.jpg" alt="不會影響宿主機"></p><p>對於虛擬機，你可以更為隨心所欲地使用，因為虛擬機系統和宿主機系統是隔離的。</p><p>很多時候，如果你並不熟悉 Linux 系統，你很可能會把配置弄得十分混亂。</p><p>所以在虛擬機裏，你可以隨意嘗試而無需擔心是否會影響到宿主機系統。換句話説，任何虛擬機的操作都不會影響到宿主機，因為它們是完全隔離的。</p><p>故此，虛擬機是你最好的試驗場，尤其是對於一些激進或具有破壞性的試驗。</p><h4 id="_3、資源可高效共享" tabindex="-1">3、資源可高效共享 <a class="header-anchor" href="#_3、資源可高效共享" aria-label="Permalink to “3、資源可高效共享”">​</a></h4><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/sharing-resources-linux-vm.jpg" alt="資源可高效共享"></p><p>如果你有十分充裕的系統資源，你可以使用虛擬機運行其他任務，從而充分利用起來這部分閒置的系統資源。例如，如果你需要一個十分私密的瀏覽環境，虛擬機將為你阻擋一切針對宿主機的追蹤器。</p><p>這可能略顯牽強，但這僅僅是一個例子。基於這樣的想法你將可以充分利用全部的系統資源。</p>',11)),i("p",null,[t[8]||(t[8]=n("而對於雙啓動方案，你需要在單獨的磁盤上在 Windows ",-1)),s(l,{href:"https://itsfoss.com/dual-boot-hdd-ssd/"},{default:p(()=>[...t[6]||(t[6]=[n("之後安裝 Linux",-1)])]),_:1}),t[9]||(t[9]=n("，或者在 Linux ",-1)),s(l,{href:"https://itsfoss.com/install-windows-after-ubuntu-dual-boot/"},{default:p(()=>[...t[7]||(t[7]=[n("之後安裝 Windows",-1)])]),_:1}),t[10]||(t[10]=n("，你需要為你的任務鎖定相應的資源。",-1))]),t[45]||(t[45]=i("p",null,"但利用虛擬機，你無需鎖定部分資源也可以使用 Linux ，也不必為了特定的任務而臨時共享資源，這樣會方便許多。",-1)),t[46]||(t[46]=i("h4",{id:"_4、多任務體驗更好",tabindex:"-1"},[n("4、多任務體驗更好 "),i("a",{class:"header-anchor",href:"#_4、多任務體驗更好","aria-label":"Permalink to “4、多任務體驗更好”"},"​")],-1)),t[47]||(t[47]=i("p",null,[i("img",{src:"https://itsfoss.com/wp-content/uploads/2022/04/multitasking-linux-vm.jpg",alt:"多任務體驗更好"})],-1)),t[48]||(t[48]=i("p",null,"有了資源共享機制，多任務會前所未有的容易。",-1)),t[49]||(t[49]=i("p",null,"在雙啓動的場景下，你需要來回重啓切換才能使用 Linux 或 Windows 。",-1)),i("p",null,[t[12]||(t[12]=n("但如果使用虛擬機，你幾乎不再需要 ",-1)),s(l,{href:"https://itsfoss.com/dual-boot-fedora-windows/"},{default:p(()=>[...t[11]||(t[11]=[n("雙啓動",-1)])]),_:1}),t[13]||(t[13]=n("，兩個系統將無縫協作並完成多任務。",-1))]),t[50]||(t[50]=o('<p>當然，你需要確認你擁有足夠的系統資源和額外的硬件（例如雙顯示器）來更高效地使用。而多任務的潛力也因 Linux 虛擬機的存在而愈發強大。</p><h4 id="_5、軟件測試更為便捷" tabindex="-1">5、軟件測試更為便捷 <a class="header-anchor" href="#_5、軟件測試更為便捷" aria-label="Permalink to “5、軟件測試更為便捷”">​</a></h4><p>有了虛擬化，你將可以創建大量的 Linux 實例，來模擬特定的使用場景，並對軟件進行測試。</p><p>例如，你可以在不同的 Linux 虛擬機中同步測試不同的軟件版本。這有豐富的使用場景，包括對開發版軟件進行測試以及 Linux 發行版的早期測試等等。</p><h4 id="_6、開發更為便捷" tabindex="-1">6、開發更為便捷 <a class="header-anchor" href="#_6、開發更為便捷" aria-label="Permalink to “6、開發更為便捷”">​</a></h4><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/development-linux-vm.jpg" alt="開發更為便捷"></p><p>當你在學習編程或者剛加入一個軟件項目的開發的時候，你會希望擁有一個沒有任何衝突和錯誤的開發環境。</p>',7)),i("p",null,[t[15]||(t[15]=n("在 Linux 虛擬機裏，你可以從零開始搭建一個不會與已經存在的環境衝突的開發環境。例如，你可以在 Ubuntu 上 ",-1)),s(l,{href:"https://itsfoss.com/install-flutter-linux/"},{default:p(()=>[...t[14]||(t[14]=[n("安裝並測試 Flutter",-1)])]),_:1}),t[16]||(t[16]=n(" 。",-1))]),t[51]||(t[51]=i("p",null,"如果環境出了問題，你可以輕而易舉地刪掉這個虛擬機，並重新開始來修正錯誤。",-1)),t[52]||(t[52]=i("p",null,"Linux 虛擬機的隔離環境是一個絕佳的開發和測試環境。",-1)),t[53]||(t[53]=i("h4",{id:"_7、學習和研究的好幫手",tabindex:"-1"},[n("7、學習和研究的好幫手 "),i("a",{class:"header-anchor",href:"#_7、學習和研究的好幫手","aria-label":"Permalink to “7、學習和研究的好幫手”"},"​")],-1)),t[54]||(t[54]=i("p",null,"Linux 值得反覆探索。除了基礎的計算任務，你可以做許多其他的事情。",-1)),i("p",null,[t[19]||(t[19]=n("你可以學習如何修改你的用户界面，",-1)),s(l,{href:"https://itsfoss.com/best-linux-desktop-environments/"},{default:p(()=>[...t[17]||(t[17]=[n("嘗試一些常見的桌面環境",-1)])]),_:1}),t[20]||(t[20]=n(" 、",-1)),s(l,{href:"https://itsfoss.com/essential-linux-applications/"},{default:p(()=>[...t[18]||(t[18]=[n("安裝大量常用軟件",-1)])]),_:1}),t[21]||(t[21]=n(" ，與此同時仍能讓一切處於掌控之中。",-1))]),t[55]||(t[55]=o('<p>如果出現問題，新建一個 Linux 虛擬機就可以解決。當然，這並不僅限於日常使用需要，還可以啓發系統管理員在其中測試他們所學的知識。</p><h4 id="_8、更容易複製和遷移" tabindex="-1">8、更容易複製和遷移 <a class="header-anchor" href="#_8、更容易複製和遷移" aria-label="Permalink to “8、更容易複製和遷移”">​</a></h4><p>虛擬機可以很容易地複製和遷移。只要其它的宿主機系統支持該虛擬化程序，你就可以很容易地遷移它，而沒有特別要求。</p><p>不論因何原因，幾次簡單的點擊就可以完成複製和遷移的任務。</p><h4 id="_9、嘗試大量的發行版" tabindex="-1">9、嘗試大量的發行版 <a class="header-anchor" href="#_9、嘗試大量的發行版" aria-label="Permalink to “9、嘗試大量的發行版”">​</a></h4><p><img src="https://itsfoss.com/wp-content/uploads/2022/04/distros-linux-vm.jpg" alt="嘗試大量的發行版"></p><p>你可以在虛擬環境下嘗試數以百計的 Linux 發行版。</p><p>你或許會認為這和第七條重複了，但是我相信，測試一個發行版是一個巨大的系統性工程，尤其是當你決定切換髮行版做為宿主機或其他用途時。</p><h4 id="_10、便於調試" tabindex="-1">10、便於調試 <a class="header-anchor" href="#_10、便於調試" aria-label="Permalink to “10、便於調試”">​</a></h4><p>不論是嚴肅的開發活動還是一般的研究，在隔離的虛擬環境中調試和除錯相對而言會更簡單。</p><p>你可以快速嘗試大量的調試方法而無需考慮影響。同時，如果你的宿主機是 Linux 系統的話，無需宿主機上的 root 權限便可以訪問和修改虛擬機中的配置文件。</p><h3 id="總而言之" tabindex="-1">總而言之 <a class="header-anchor" href="#總而言之" aria-label="Permalink to “總而言之”">​</a></h3><p>如果你不熟悉正在使用的系統或者依賴不同的操作系統工作，虛擬機將是協助你工作的一大利器。</p><p>Linux 虛擬機可以廣泛用於開發、學習、試驗或任何特定用途。</p><p>你在虛擬機中使用過 Linux 嗎？都有哪些應用場景呢？歡迎留言評論！</p><hr>',16)),i("p",null,[t[23]||(t[23]=n("via: ",-1)),s(l,{href:"https://itsfoss.com/why-linux-virtual-machine/"},{default:p(()=>[...t[22]||(t[22]=[n("https://itsfoss.com/why-linux-virtual-machine/",-1)])]),_:1})]),i("p",null,[t[28]||(t[28]=n("作者：",-1)),s(l,{href:"https://itsfoss.com/author/ankush/"},{default:p(()=>[...t[24]||(t[24]=[n("Ankush Das",-1)])]),_:1}),t[29]||(t[29]=n(" 選題：",-1)),s(l,{href:"https://github.com/lkxed"},{default:p(()=>[...t[25]||(t[25]=[n("lkxed",-1)])]),_:1}),t[30]||(t[30]=n(" 譯者：",-1)),s(l,{href:"https://github.com/PeterPan0106"},{default:p(()=>[...t[26]||(t[26]=[n("PeterPan0106",-1)])]),_:1}),t[31]||(t[31]=n(" 校對：",-1)),s(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[27]||(t[27]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[34]||(t[34]=n("本文由 ",-1)),s(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[32]||(t[32]=[n("LCTT",-1)])]),_:1}),t[35]||(t[35]=n(" 原創編譯，",-1)),s(l,{href:"https://linux.cn/"},{default:p(()=>[...t[33]||(t[33]=[n("Linux中國",-1)])]),_:1}),t[36]||(t[36]=n(" 榮譽推出",-1))])])}const w=u(d,[["render",x]]);export{k as __pageData,w as default};
